import { Quaternion, Vector3 } from 'three';

// Screen-space rotation: both axes contribute, so diagonal drags tumble the
// board naturally. Premultiplication keeps the axes aligned with the viewer.
export function rotateBoard(rotation, dx, dy, viewportSpan) {
  const distance = Math.hypot(dx, dy);
  if (distance === 0) return rotation;
  const radiansPerPixel = Math.PI / Math.max(220, viewportSpan * 0.45);
  const axis = new Vector3(dy, dx, 0).normalize();
  return rotation.premultiply(new Quaternion().setFromAxisAngle(axis, distance * radiansPerPixel)).normalize();
}
