import { useCallback, useEffect, useRef, useState } from 'react';
import { soundCodes, randomKeys, beginReaction, pressReaction, releaseReaction } from './keyboardGame.mjs';

const idle = () => ({ targets: [], down: [], phase: 'idle', startedAt: null, reactionMs: null });

export default function useKeyboardGame(active, onClose) {
  const [state, setState] = useState(idle);
  const current = useRef(state);
  const [pressed, setPressed] = useState([]);
  const [round, setRound] = useState(0);
  const [volume, setVolume] = useState(0.55);
  const [error, setError] = useState(false);
  const audio = useRef();
  const volumeRef = useRef(volume);
  const errorTimer = useRef();
  const releases = useRef(new Map());
  volumeRef.current = volume;
  const update = useCallback(next => { current.current = next; setState(next); }, []);

  const unlockAudio = useCallback(() => {
    const Audio = window.AudioContext || window.webkitAudioContext;
    if (Audio && !audio.current) audio.current = new Audio();
    audio.current?.resume().catch(() => {});
  }, []);
  const start = useCallback(() => {
    unlockAudio(); clearTimeout(errorTimer.current); setError(false);
    update(beginReaction(randomKeys(), performance.now(), current.current.down));
    setRound(value => value + 1);
  }, [unlockAudio, update]);

  const sound = useCallback(code => {
    unlockAudio();
    if (audio.current && volumeRef.current > 0) {
      const ctx = audio.current, now = ctx.currentTime;
      const note = Math.max(0, soundCodes.indexOf(code));
      const pitch = note < 36 ? note : 36 + (note - 36) * 0.2;
      const oscillator = ctx.createOscillator(), gain = ctx.createGain();
      oscillator.type = 'triangle'; oscillator.frequency.value = 130.81 * 2 ** (pitch / 12);
      gain.gain.setValueAtTime(0.0001, now);
      gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volumeRef.current * 0.15), now + 0.008);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.85);
      oscillator.connect(gain); gain.connect(ctx.destination); oscillator.start(now); oscillator.stop(now + 0.86);
      oscillator.onended = () => { oscillator.disconnect(); gain.disconnect(); };
    }
  }, [unlockAudio]);
  // Clicking the 3D key previews its note; only physical key holds score a round.
  const play = useCallback(code => {
    sound(code); setPressed(value => value.includes(code) ? value : [...value, code]);
    clearTimeout(releases.current.get(code));
    releases.current.set(code, setTimeout(() => {
      setPressed(value => value.filter(key => key !== code)); releases.current.delete(code);
    }, 180));
  }, [sound]);

  useEffect(() => {
    if (!active) {
      update(idle()); setPressed([]); setRound(0); setError(false); clearTimeout(errorTimer.current);
      return undefined;
    }
    const keydown = event => {
      if (event.key === 'Escape') { event.preventDefault(); onClose(); return; }
      if (event.repeat || event.metaKey || event.ctrlKey || event.altKey || event.code === 'Tab') return;
      if (event.target instanceof HTMLInputElement && event.code.startsWith('Arrow')) return;
      if (event.target instanceof HTMLButtonElement && ['Space', 'Enter'].includes(event.code)) return;
      if (!soundCodes.includes(event.code)) return;
      event.preventDefault(); sound(event.code);
      const result = pressReaction(current.current, event.code, performance.now());
      update(result.state);
      if (result.wrong) {
        clearTimeout(errorTimer.current); setError(true);
        errorTimer.current = setTimeout(() => setError(false), 240);
      }
    };
    const keyup = event => update(releaseReaction(current.current, event.code, performance.now()));
    const blur = () => {
      // Pause a live attempt when the window loses focus, without leaving stuck keys.
      const s = current.current;
      update({ ...s, down: [], ...(s.phase === 'ready' || s.phase === 'waiting' ? { phase: 'idle', targets: [], startedAt: null } : {}) });
      setPressed([]);
    };
    const visibility = () => { if (document.hidden) blur(); };
    window.addEventListener('keydown', keydown); window.addEventListener('keyup', keyup);
    window.addEventListener('blur', blur); document.addEventListener('visibilitychange', visibility);
    return () => {
      window.removeEventListener('keydown', keydown); window.removeEventListener('keyup', keyup);
      window.removeEventListener('blur', blur); document.removeEventListener('visibilitychange', visibility);
    };
  }, [active, onClose, sound, update]);
  useEffect(() => {
    const timers = releases.current;
    return () => { clearTimeout(errorTimer.current); timers.forEach(clearTimeout); audio.current?.close().catch(() => {}); };
  }, []);
  return { targets: state.phase === 'waiting' ? [] : state.targets, pressed: [...new Set([...state.down, ...pressed])],
    phase: state.phase, reactionMs: state.reactionMs, error, round, volume, setVolume, start, play, unlockAudio };
}
