export const initialPuzzle = { hasKey: false, unlocked: false };
export function puzzleReducer(state, action) {
  if (action.type === 'collect' && !state.unlocked) return { ...state, hasKey: true };
  if (action.type === 'unlock' && state.hasKey && !state.unlocked) return { ...state, hasKey: false, unlocked: true };
  return state;
}
export function drawerAction({ hasKey, unlocked, open }) {
  return !unlocked ? (hasKey ? 'unlock' : 'rattle') : (open ? 'close' : 'open');
}
export function lockedDrawerOffset(seconds) {
  if (seconds < 0 || seconds >= .75) return 0;
  if (seconds < .16) return .055 * Math.sin(seconds / .16 * Math.PI / 2);
  const t = seconds - .16;
  return .055 * Math.exp(-11 * t) * (.72 + .28 * Math.cos(t * 55));
}
