import React, { useCallback, useEffect, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { projects } from '../../constants/projectData';
import './ProjectGallery.css';

const projectHref = link => /^https?:\/\//.test(link.trim())
  ? link.trim() : `${process.env.PUBLIC_URL}/assets/${link.trim()}`;

export default function ProjectGallery({ initialIndex = 0, onIndexChange, onClose, reducedMotion }) {
  const [activeIndex, setActiveIndex] = useState(initialIndex);
  const selected = projects[activeIndex];
  useEffect(() => { onIndexChange?.(activeIndex); }, [activeIndex, onIndexChange]);
  const dialogRef = useRef(null);
  const backRef = useRef(null);
  const dismiss = useCallback(() => onClose(), [onClose]);

  useEffect(() => {
    const previous = document.activeElement;
    backRef.current?.focus();
    return () => {
      requestAnimationFrame(() => {
        const target = previous instanceof HTMLElement && previous.isConnected && previous.matches('button, a, [tabindex]') ? previous : document.querySelector('.carousel-open-project');
        target?.focus({ preventScroll: true });
      });
    };
  }, []);
  useEffect(() => {
    backRef.current?.focus();
    const handleKey = event => {
      if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); dismiss(); }
      if (event.key === 'Tab') {
        const elements = [...dialogRef.current.querySelectorAll('button:not(:disabled), a[href], [tabindex="0"]')].filter(element => element.tabIndex >= 0 && element.getClientRects().length);
        const first = elements[0], last = elements[elements.length - 1];
        if (event.shiftKey && (document.activeElement === first || !dialogRef.current.contains(document.activeElement))) { event.preventDefault(); last?.focus(); }
        else if (!event.shiftKey && (document.activeElement === last || !dialogRef.current.contains(document.activeElement))) { event.preventDefault(); first?.focus(); }
      }
    };
    document.addEventListener('keydown', handleKey, true);
    return () => document.removeEventListener('keydown', handleKey, true);
  }, [dismiss]);

  const transition = { duration: reducedMotion ? 0 : .32, ease: [.22, 1, .36, 1] };
  return <motion.section ref={dialogRef} className="project-gallery project-gallery--detail" role="dialog" aria-modal="true" aria-labelledby="project-gallery-title"
    initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={transition}>
    <header className="project-gallery-header">
      <button ref={backRef} className="project-gallery-back" onClick={dismiss}>← <span>Back to the carousel</span><kbd>Esc</kbd></button>
      <h2 id="project-gallery-title">A closer look</h2>
      <span className="project-gallery-signature">Marco Guo</span>
    </header>
    <AnimatePresence mode="wait" initial={false}>
      <motion.article className="project-gallery-detail" key={selected.id} initial={{ opacity: 0, y: reducedMotion ? 0 : 18 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={transition}>
        <div className="project-gallery-image"><img src={selected.image} alt={selected.title} /></div>
        <div className="project-gallery-story">
          <span className="project-gallery-category">{selected.tag}</span>
          <h3>{selected.title}</h3>
          <p>{selected.description}</p>
          <ul className="project-gallery-tools" aria-label="Tools and technologies">{selected.techStack.map(tech => <li key={tech}>{tech}</li>)}</ul>
          <div className="project-gallery-links">
            {selected.link && <a href={projectHref(selected.link)} target="_blank" rel="noopener noreferrer">{selected.link.includes('figma.com') ? 'View prototype' : selected.link.endsWith('.pdf') ? 'Read project' : 'View project'} <span aria-hidden="true">↗</span></a>}
            {selected.github && <a href={selected.github} target="_blank" rel="noopener noreferrer">GitHub <span aria-hidden="true">↗</span></a>}
          </div>
          <nav className="project-gallery-detail-nav" aria-label="Browse project details">
            <button disabled={activeIndex === 0} onClick={() => { setActiveIndex(activeIndex - 1); }}>← Previous</button>
            <span>{activeIndex + 1} / {projects.length}</span>
            <button disabled={activeIndex === projects.length - 1} onClick={() => { setActiveIndex(activeIndex + 1); }}>Next →</button>
          </nav>
        </div>
      </motion.article>
    </AnimatePresence>
  </motion.section>;
}
