function Label({ text, position, width = 0.2, height = 0.045, color = '#f7f3e7', background = null, rotation }) {
  const map = useMemo(() => {
    const canvas = document.createElement('canvas'); canvas.width = 512; canvas.height = 128;
    const ctx = canvas.getContext('2d');
    if (background) { ctx.fillStyle = background; ctx.fillRect(0, 0, 512, 128); }
    ctx.fillStyle = color; ctx.font = 'bold 66px sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, 256, 64, 500);
    const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace; return texture;
  }, [text, color, background]);
  useEffect(() => () => map.dispose(), [map]);
  return <mesh position={position} rotation={rotation}><planeGeometry args={[width, height]} />
    <meshBasicMaterial map={map} transparent depthWrite={false} /></mesh>;
}

function ProfileFrame({ profile, onOpen, night, reducedMotion }) {
  const face = useRef();
  const rim = useRef();
  const glow = useRef();
  useFrame((_, dt) => {
    const level = THREE.MathUtils.damp(face.current.emissiveIntensity, night ? .85 : 0, 4, reducedMotion ? 10 : dt);
    face.current.emissiveIntensity = level;
    rim.current.emissiveIntensity = level * 1.8;
    glow.current.intensity = level * .18;
  });
  const map = useMemo(() => {
    const canvas = document.createElement('canvas'); canvas.width = 384; canvas.height = 384;
    const ctx = canvas.getContext('2d'); ctx.fillStyle = '#f5f0e4'; ctx.fillRect(0, 0, 384, 384);
    const [w, h, , , paths] = profile.icon.icon;
    ctx.save(); ctx.translate(80, 54); ctx.scale(224 / w, 224 / h); ctx.fillStyle = profile.color;
    for (const path of Array.isArray(paths) ? paths : [paths]) ctx.fill(new Path2D(path));
    ctx.restore(); ctx.fillStyle = '#4d493f'; ctx.font = '26px sans-serif'; ctx.textAlign = 'center'; ctx.fillText(profile.name, 192, 333);
    const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace; return texture;
  }, [profile]);
  useEffect(() => () => map.dispose(), [map]);
  return <group name={`${profile.name} profile frame`} position={[0.93, profile.y, -2.355]}
    onClick={event => { event.stopPropagation(); if (event.delta <= 5) onOpen(profile); }}>
    <InteractionLabel name={profile.name} position={[0, 0.38, 0.05]}>
    <mesh position={[0, 0, -.008]}>
      <boxGeometry args={[.565, .535, .02]} />
      <meshStandardMaterial ref={rim} color='#c8b79b' emissive='#ffdcb2' emissiveIntensity={0} />
    </mesh>
    <pointLight ref={glow} position={[0, 0, .13]} color='#ffe4ba' intensity={0} distance={.95} decay={2} />
    <Box args={[0.55, 0.52, 0.055]} color='#795638' radius={0.009} />
    <mesh position={[0, 0, 0.03]}><planeGeometry args={[0.475, 0.445]} /><meshStandardMaterial ref={face} map={map} emissiveMap={map} emissive='#fff3df' emissiveIntensity={0} roughness={0.8} /></mesh></InteractionLabel>
  </group>;
}

export function ProfileFrames({ onOpen, night, reducedMotion }) {
  return <group>{profiles.map(profile => <ProfileFrame key={profile.name} profile={profile} onOpen={onOpen} night={night} reducedMotion={reducedMotion} />)}</group>;
}

