const keyHome = new THREE.Vector3(0, -0.112, 0.07);
const keyRotation = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), -Math.PI / 2);

function LakeKey({ inspecting, onInspect, reducedMotion, visible }) {
  const cube = useRef();
  useFrame((_, dt) => { if (cube.current && !reducedMotion) { cube.current.rotation.y += dt * .85; cube.current.rotation.x += dt * .3; } });
  const { ref, handlers } = useInspection({ inspecting, onInspect, reducedMotion, homePosition: keyHome, homeRotation: keyRotation, distance: 0.92 });
  return <group ref={ref} name='Hidden Rusty Lake inspired key' position={keyHome} quaternion={keyRotation} {...(visible || inspecting ? handlers : {})}
    visible={visible || inspecting}>
    <InteractionLabel name="Rusty Lake key" available={visible || inspecting} position={[0, 0.28, 0.12]}>
    <mesh><boxGeometry args={[0.2, 0.4, 0.045]} /><meshBasicMaterial transparent opacity={0} depthWrite={false} /></mesh>
    <mesh position={[0, 0.125, 0]} castShadow><torusGeometry args={[0.067, 0.019, 12, 32]} />
      <meshStandardMaterial color='#a9843e' metalness={0.65} roughness={0.6} /></mesh>
    <Box args={[0.028, 0.24, 0.028]} position={[0, -0.043, 0]} color='#b08a42' radius={0.006} />
    <Box args={[0.085, 0.028, 0.035]} position={[0.025, -0.148, 0]} color='#ab8337' radius={0.004} />
    <Box args={[0.029, 0.044, 0.035]} position={[0.054, -0.128, 0]} color='#ab8337' radius={0.003} />
    <Box args={[0.055, 0.025, 0.035]} position={[0.025, -0.093, 0]} color='#ab8337' radius={0.003} />
    <mesh ref={cube} position={[0, 0.125, 0]} rotation={[0, 0, Math.PI / 4]} castShadow>
      <boxGeometry args={[0.038, 0.038, 0.038]} /><meshStandardMaterial color='#303128' roughness={0.8} /></mesh></InteractionLabel>
  </group>;
}

export function SecretDrawer({ y, hasKey, map, inspecting, onInspect, reducedMotion, puzzle, onUnlock, sound }) {
  const [open, setOpen] = useState(false);
  const [exposed, setExposed] = useState(false);
  const slide = useRef();
  const attempt = useRef(null);
  const [dissolving, setDissolving] = useState(false);
  const [lockGone, setLockGone] = useState(puzzle.unlocked);
  const interact = event => {
    event.stopPropagation(); if (event.delta > 5 || dissolving) return;
    if (inspecting) { onInspect(false); return; }
    if (hasKey) { setOpen(value => !value); return; }
    const action = drawerAction({ ...puzzle, open });
    if (action === 'rattle') { attempt.current = 0; sound('locked'); }
    else if (action === 'unlock') { sound('unlock'); onUnlock(); setDissolving(true); }
    else setOpen(action === 'open');
  };
  useFrame((_, delta) => {
    const target = open ? 0.64 : 0;
    if (attempt.current !== null) {
      attempt.current += delta;
      slide.current.position.z = reducedMotion ? 0 : lockedDrawerOffset(attempt.current);
      if (attempt.current >= .75) attempt.current = null;
    } else slide.current.position.z = reducedMotion ? target : THREE.MathUtils.damp(slide.current.position.z, target, 8, delta);
    const next = slide.current.position.z > 0.43;
    if (next !== exposed) setExposed(next);
  });
  return <group ref={slide} position={[0, y, 0]} name={hasKey ? 'Upper secret drawer' : 'Lower drawer'}>
    <group onClick={interact}>
      <Box args={[0.94, 0.36, 0.055]} position={[0, 0, 0.3275]} color='#b99470' map={map} />
      <Box args={[0.22, 0.03, 0.04]} position={[0, 0.06, 0.375]} color='#544333' />
      <Box args={[0.88, 0.035, 0.62]} position={[0, -0.1525, 0]} color='#98784e' map={map} />
      {[-0.433, 0.433].map(x => <Box key={x} args={[0.034, 0.26, 0.62]} position={[x, -0.01, 0]} color='#ba9869' map={map} />)}
      <Box args={[0.88, 0.26, 0.035]} position={[0, -0.01, -0.293]} color='#ba9869' map={map} />
      <Box args={[0.83, 0.004, 0.56]} position={[0, -0.133, 0]} color='#504f3e' radius={0.001} />
      {!hasKey && !lockGone && <RustyLock dissolving={dissolving} reducedMotion={reducedMotion} onGone={() => { setLockGone(true); setDissolving(false); setOpen(true); }} />}
    </group>
    {hasKey && !puzzle.unlocked && <LakeKey inspecting={inspecting} onInspect={onInspect} reducedMotion={reducedMotion} visible={exposed && !puzzle.hasKey} />}
  </group>;
}
