import React, { useRef } from 'react';
import { keyLabel } from './keyboardGame.mjs';
import './KeyboardHUD.css';

export default function KeyboardHUD({ game, onClose }) {
  const drag = useRef();
  const success = game.phase === 'success';
  return <section className={`keyboard-hud ${game.error ? 'keyboard-error' : ''}`} aria-label='Keyboard reaction test'>
    <div className='keyboard-heading'><span>KEYBOARD / REACTION TEST</span>
      <h2>{success ? <><strong className='reaction-time'>{game.reactionMs}</strong> <span className='reaction-unit'>ms</span></> : game.phase === 'ready' ? 'Ready. Set. Press.' : game.phase === 'waiting' ? 'Release all keys.' : 'How quick are you?'}</h2>
      <p role='status' aria-live='polite'>{game.error ? 'Wrong key — try the glowing keys together.' : success ? 'All keys held together. Click the dial for another round.' : game.phase === 'ready' ? 'Hold all glowing keys at the same time on your keyboard.' : game.phase === 'waiting' ? 'The next round begins once every key is released.' : 'Click the flashing dial, then press the 1–5 glowing keys together.'}</p>
      <div className='keyboard-targets' aria-label='Keys to hold together'>{game.targets.map(code => <kbd className={game.pressed.includes(code) ? 'key-held' : ''} key={code}>{keyLabel(code)}</kbd>)}</div>
      {game.round > 0 && <small className='reaction-round'>ROUND {String(game.round).padStart(2, '0')}{success ? ' · COMPLETE' : ''}</small>}
      {success && <output className='sr-only' aria-live='polite'>Reaction time: {game.reactionMs} milliseconds</output>}
    </div>
    <div className='keyboard-volume'>
      <button className='volume-dial' aria-label='Start a new reaction test' title='Click to start · Drag to adjust volume'
        onPointerDown={event => { event.currentTarget.setPointerCapture(event.pointerId); drag.current = { x: event.clientX, y: event.clientY, volume: game.volume, moved: false }; }}
        onPointerMove={event => { const d = drag.current; if (!d) return;
          const dx = event.clientX - d.x, dy = d.y - event.clientY; if (Math.hypot(dx, dy) > 4) d.moved = true;
          game.setVolume(Math.max(0, Math.min(1, d.volume + (dx + dy) / 180)));
        }}
        onPointerUp={event => { event.currentTarget.releasePointerCapture(event.pointerId); }}
        onPointerCancel={() => { drag.current = null; }}
        onClick={() => { if (!drag.current?.moved) game.start(); drag.current = null; }}>
        <span style={{ transform: `rotate(${-135 + game.volume * 270}deg)` }} />
      </button>
      <label htmlFor='keyboard-volume'>VOLUME <strong>{Math.round(game.volume * 100)}%</strong></label>
      <input id='keyboard-volume' aria-label='Keyboard volume' type='range' min='0' max='100' value={Math.round(game.volume * 100)} onChange={event => game.setVolume(Number(event.target.value) / 100)} />
      <small>Click to test · Drag for volume</small>
    </div>
    <button className='keyboard-exit' onClick={onClose}>← Back to the room <kbd>ESC</kbd></button>
  </section>;
}
