import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useTexture } from '@react-three/drei';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { Box } from './primitives';
import { pegboardCards } from './pegboardLayout.mjs';

const papers = ['#f9f7ee', '#f2f3ee', '#f7f0df', '#f3f2f7'];
const urls = pegboardCards.map(card => `${process.env.PUBLIC_URL}/assets/skills/${card.file}`);

function PinnedSkill({ card, texture, index, reducedMotion, selected, onSelect }) {
  const pivot = useRef();
  const icon = useRef();
  const motion = useRef({ angle: card.angle, speed: 0 });
  const [hovered, setHovered] = useState(false);
  const paper = papers[index % papers.length];
  const map = useMemo(() => {
    const canvas = document.createElement('canvas'); canvas.width = 256; canvas.height = 320;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = paper; ctx.fillRect(0, 0, 256, 320);
    ctx.fillStyle = '#4a4a44'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.font = '500 25px -apple-system, sans-serif'; ctx.fillText(card.name, 128, 280, 226);
    const result = new THREE.CanvasTexture(canvas);
    result.colorSpace = THREE.SRGBColorSpace; result.anisotropy = 8;
    return result;
  }, [card.name, paper]);
  const iconMap = useMemo(() => {
    const canvas = document.createElement('canvas'); canvas.width = 256; canvas.height = 256;
    const ctx = canvas.getContext('2d'), img = texture.image;
    const fit = Math.min(256 / img.width, 256 / img.height);
    const width = img.width * fit, height = img.height * fit;
    ctx.drawImage(img, (256 - width) / 2, (256 - height) / 2, width, height);
    const result = new THREE.CanvasTexture(canvas); result.colorSpace = THREE.SRGBColorSpace; result.anisotropy = 8;
    return result;
  }, [texture]);
  useEffect(() => () => iconMap.dispose(), [iconMap]);
  useEffect(() => () => map.dispose(), [map]);
  useFrame((_, delta) => {
    const m = motion.current;
    if (reducedMotion) { m.angle = card.angle; m.speed = 0; }
    else {
      const dt = Math.min(delta, 1 / 30);
      const target = card.angle + (hovered ? (index % 2 ? -.035 : .035) : 0);
      m.speed += ((target - m.angle) * 95 - m.speed * 10) * dt;
      m.angle += m.speed * dt;
    }
    if (pivot.current) pivot.current.rotation.z = m.angle;
    if (icon.current) {
      const scale = reducedMotion ? (selected ? 1.2 : 1) : THREE.MathUtils.damp(icon.current.scale.x, selected ? 1.2 : 1, 12, delta);
      icon.current.scale.setScalar(scale);
    }
  });
  const offset = card.height / 2 - .025;
  const iconSize = Math.min(card.height * .54, card.width * .74);
  return <group position={[card.x, card.y, .052]} name={`${card.name} pinned skill`}
    onPointerOver={event => { event.stopPropagation(); setHovered(true); }} onPointerOut={() => setHovered(false)}
    onClick={event => { event.stopPropagation(); if (event.delta <= 5) onSelect(); }}>
    <group ref={pivot} rotation={[0, 0, card.angle]}>
      <Box args={[card.width, card.height, .009]} position={[0, -offset, 0]} color={paper} radius={.003} />
      <mesh position={[0, -offset, .0047]}>
        <planeGeometry args={[card.width - .003, card.height - .003]} />
        <meshBasicMaterial map={map} toneMapped={false} />
      </mesh>
      <mesh ref={icon} position={[0, -offset + card.height * .02, .0052]}>
        <planeGeometry args={[iconSize, iconSize]} />
        <meshBasicMaterial map={iconMap} transparent depthWrite={false} toneMapped={false} />
      </mesh>
    </group>
    <mesh position={[0, 0, -.003]} rotation={[Math.PI / 2, 0, 0]} castShadow>
      <cylinderGeometry args={[.0035, .0035, .042, 10]} />
      <meshStandardMaterial color='#858a8b' metalness={.8} roughness={.3} />
    </mesh>
    <mesh position={[0, 0, .02]} scale={[1, 1, .5]} castShadow>
      <sphereGeometry args={[.012, 16, 10]} />
      <meshStandardMaterial color={index % 4 === 0 ? '#b9a57a' : '#bdc1c0'} metalness={.75} roughness={.28} />
    </mesh>
  </group>;
}

export default function PegboardSkills({ reducedMotion, focused, onFocus }) {
  const [selected, setSelected] = useState(null);
  useEffect(() => { if (!focused) setSelected(null); }, [focused]);
  const textures = useTexture(urls);
  return <group name='My skillset' onPointerMissed={() => setSelected(null)}>{pegboardCards.map((card, i) =>
    <PinnedSkill key={card.name} card={card} index={i} texture={textures[i]} reducedMotion={reducedMotion} selected={selected === card.name}
      onSelect={() => { if (!focused) onFocus(); else setSelected(value => value === card.name ? null : card.name); }} />)}</group>;
}
