import React, { useEffect, useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';

export default function RustyLock({ dissolving, reducedMotion, onGone }) {
  const time = useRef(0), finished = useRef(false), dust = useRef();
  const material = useMemo(() => new THREE.ShaderMaterial({
    uniforms: { progress: { value: 0 } },
    vertexShader: `varying vec3 vP; varying vec3 vN; void main(){ vP=position; vN=normalize(normalMatrix*normal); gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
    fragmentShader: `uniform float progress; varying vec3 vP; varying vec3 vN;
      float grain(vec3 p){ return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453); }
      void main(){ float n=grain(floor(vP*460.0)); if(n<progress) discard;
        float light=.48+.52*max(0.0,dot(normalize(vN),normalize(vec3(-.4,.8,1.0))));
        vec3 brass=mix(vec3(.19,.12,.075),vec3(.56,.39,.19),grain(floor(vP*190.0)))*light;
        float edge=progress>0.0 ? 1.0-smoothstep(0.0,.045,n-progress) : 0.0;
        gl_FragColor=vec4(mix(brass,vec3(.88,.6,.3),edge*.7),1.0); }`,
  }), []);
  const particles = useMemo(() => {
    const positions = new Float32Array(120 * 3), seeds = [];
    let seed = 742;
    const random = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
    for (let i = 0; i < 120; i++) seeds.push([random() * .14 - .07, random() * .18 - .06, random() * .05, random(), random()]);
    const geometry = new THREE.BufferGeometry(); geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    return { geometry, seeds };
  }, []);
  useEffect(() => () => { material.dispose(); particles.geometry.dispose(); }, [material, particles]);
  useFrame((_, dt) => {
    if (!dissolving || finished.current) return;
    const t = time.current = reducedMotion ? 1 : Math.min(1, time.current + dt / 1.2);
    material.uniforms.progress.value = t;
    const attr = particles.geometry.attributes.position;
    particles.seeds.forEach(([x, y, z, a, b], i) => attr.setXYZ(i, x + t * (.12 + a * .35), y + t * (.14 + b * .3), z + t * a * .18));
    attr.needsUpdate = true; dust.current.material.opacity = (1 - t) * .8;
    if (t >= 1) { finished.current = true; onGone(); }
  });
  return <group position={[0, -.055, .4]} name='Rusty Lake padlock'>
    <mesh material={material} castShadow><boxGeometry args={[.145, .135, .048]} /></mesh>
    <mesh material={material} position={[0, .067, 0]}><torusGeometry args={[.047, .009, 10, 24, Math.PI]} /></mesh>
    {!dissolving && <group position={[0, 0, .025]}>
      <mesh><circleGeometry args={[.014, 20]} /><meshBasicMaterial color='#181b1a' /></mesh>
      <mesh position={[0, -.017, 0]}><planeGeometry args={[.012, .028]} /><meshBasicMaterial color='#181b1a' /></mesh>
      {[-.056, .056].flatMap(x => [-.05, .05].map(y => <mesh key={`${x}-${y}`} position={[x, y, .001]}><circleGeometry args={[.004, 10]} /><meshBasicMaterial color='#b09b6b' /></mesh>))}
    </group>}
    <points ref={dust} geometry={particles.geometry} visible={dissolving && !reducedMotion} frustumCulled={false}>
      <pointsMaterial color='#d1b18d' transparent opacity={0} size={.006} depthWrite={false} />
    </points>
  </group>;
}
