export default function MarcoFigurine({ inspecting, onInspect, reducedMotion }) {
  const { ref, handlers } = useInspection({ inspecting, onInspect, reducedMotion, homePosition, homeRotation, framing, wheelMode: 'zoom' });
  return <group ref={ref} name='Marco avatar figurine' position={homePosition} quaternion={homeRotation} {...handlers}>
    <InteractionLabel name='Mini Marco' position={[0, .36, 0]}>
      <group scale={scale} position={[0, -1.23 * scale, 0]}><MarcoSculpture /></group>
    </InteractionLabel>
  </group>;
}
