import React from 'react';
import achievements from '../../constants/achivements';

export default function ExperienceScreen() {
  return <section className='experience-screen' aria-label='Marco experience timeline' onPointerDown={event => event.stopPropagation()} onWheel={event => event.stopPropagation()}>
    <header><div><span>MARCO GUO</span><h1>Experience timeline</h1></div><small>Scroll to explore ↓</small></header>
    <div className='experience-scroll' tabIndex={0} aria-label='Scroll through all experience details'>
      {[...achievements].reverse().map(item => <article key={item.title}>
        <time>{item.date}</time><h2>{item.title}</h2><span className='experience-location'>{item.location}</span><p>{item.description}</p>
      </article>)}
    </div>
  </section>;
}
