import React, { useEffect, useMemo } from 'react';
import * as THREE from 'three';

const centre = new THREE.Vector3(0, 1.77, -.09);
const radii = new THREE.Vector3(.84, .78, .67);
const shades = ['#bbb9c2', '#bfbdc6', '#b7b5be', '#c1bfc8'];

function scalpPoint(theta, phi, relief = 0) {
  const direction = new THREE.Vector3(Math.sin(theta) * Math.sin(phi), Math.cos(theta), Math.sin(theta) * Math.cos(phi));
  const normal = direction.clone().divide(radii).normalize();
  return direction.multiply(radii).add(centre).addScaledVector(normal, relief);
}

function hairline(phi) {
  const back = (1 - Math.cos(phi)) / 2;
  return 1.19 + 1.43 * back * back;
}

function finishGeometry(positions, indices) {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

// The recessed scalp joins all roots; individual raised locks provide the visible surface.
function makeScalp() {
  const rows = 40, columns = 96, positions = [], indices = [];
  for (let row = 0; row <= rows; row++) {
    for (let col = 0; col <= columns; col++) {
      const phi = col / columns * Math.PI * 2;
      positions.push(...scalpPoint(row / rows * hairline(phi), phi, -.012).toArray());
      if (row < rows && col < columns) {
        const a = row * (columns + 1) + col, b = a + columns + 1;
        indices.push(a, b, a + 1, b, b + 1, a + 1);
      }
    }
  }
  return finishGeometry(positions, indices);
}

// Each lock wraps around the skull, with a convex cross-section and two sculpted channels.
// The underside and perimeter are closed so the rear and crown remain solid when rotated.
function makeLock({ phi, start, end, width, sweep, height, lift = 0 }) {
  const rows = 32, columns = 24, positions = [], indices = [];
  const layerSize = (rows + 1) * (columns + 1);
  for (let layer = 0; layer < 2; layer++) {
    for (let row = 0; row <= rows; row++) {
      const t = row / rows;
      const theta = THREE.MathUtils.lerp(start, end, t);
      const taper = Math.max(.015, Math.pow(Math.sin(Math.PI * t), .32));
      const flow = phi + sweep * (1 - t) ** 1.4;
      for (let col = 0; col <= columns; col++) {
        const across = col / columns * 2 - 1;
        const dome = Math.pow(Math.max(0, 1 - across * across), .65);
        const channels = Math.exp(-1 * ((across - .40) / .085) ** 2)
          + Math.exp(-1 * ((across + .37) / .085) ** 2);
        const relief = layer === 0
          ? -.006 + lift * Math.sin(Math.PI * t) + taper * (height * dome - .008 * channels)
          : -.021;
        positions.push(...scalpPoint(theta, flow + across * width * taper, relief).toArray());
        if (row < rows && col < columns) {
          const a = layer * layerSize + row * (columns + 1) + col, b = a + columns + 1;
          indices.push(...(layer === 0 ? [a, b, a + 1, b, b + 1, a + 1] : [a, a + 1, b, b, a + 1, b + 1]));
        }
      }
    }
  }
  const edge = [];
  for (let col = 0; col <= columns; col++) edge.push(col);
  for (let row = 1; row <= rows; row++) edge.push(row * (columns + 1) + columns);
  for (let col = columns - 1; col >= 0; col--) edge.push(rows * (columns + 1) + col);
  for (let row = rows - 1; row > 0; row--) edge.push(row * (columns + 1));
  for (let i = 0; i < edge.length; i++) {
    const a = edge[i], b = edge[(i + 1) % edge.length];
    indices.push(a, b, a + layerSize, b, b + layerSize, a + layerSize);
  }
  return finishGeometry(positions, indices);
}

export default function SculptedHair() {
  const geometries = useMemo(() => {
    const locks = [];
    // Long swept crown locks radiate from a slightly off-centre part.
    for (let i = 0; i < 20; i++) {
      const phi = i / 20 * Math.PI * 2;
      locks.push(makeLock({ phi, start: .035, end: Math.min(hairline(phi) + .04, 1.80),
        width: .177, sweep: .28, height: .055 + (i % 3) * .005 }));
    }
    // Offset rows at the occiput and nape overlap like sculpted, feathered strands.
    for (let row = 0; row < 2; row++) {
      const count = row === 0 ? 13 : 11;
      for (let i = 0; i < count; i++) {
        const phi = Math.PI - 1.18 + (i + .5 * row) / (count - 1) * 2.30;
        locks.push(makeLock({ phi, start: 1.08 + row * .63,
          end: Math.min(2.18 + row * .48 + .04 * Math.sin(i * 2.3), hairline(phi) + .04),
          width: .15, sweep: .12 * Math.sin(phi), height: .060, lift: .012 }));
      }
    }
    return [makeScalp(), ...locks];
  }, []);
  useEffect(() => () => geometries.forEach(geometry => geometry.dispose()), [geometries]);
  return <group name='Layered crown, back and nape hair with sculpted strand grooves'>
    {geometries.map((geometry, i) => <mesh key={i} castShadow receiveShadow>
      <primitive object={geometry} attach='geometry' />
      <meshPhysicalMaterial color={i === 0 ? '#aaa8b2' : shades[(i - 1) % shades.length]}
        roughness={.51} clearcoat={.18} clearcoatRoughness={.4} />
    </mesh>)}
  </group>;
}
