import { useEffect, useMemo, useRef } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { rotateBoard } from './boardRotation.mjs';

export default function useInspection({ inspecting, onInspect, reducedMotion, homePosition, homeRotation, distance = 3.65, framing, wheelMode = 'rotate' }) {
  const ref = useRef();
  const orientation = useRef(new THREE.Quaternion());
  const drag = useRef(null);
  const zoom = useRef(1);
  const pan = useRef(new THREE.Vector2());
  const { camera, gl, size, controls } = useThree();
  const framedDistance = framing ? Math.max(framing.height, framing.width / (size.width / size.height))
    / (2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * 0.9) : distance;
  const scratch = useMemo(() => ({ position: new THREE.Vector3(), rotation: new THREE.Quaternion(), parent: new THREE.Quaternion() }), []);
  useEffect(() => {
    if (inspecting) { orientation.current.identity(); zoom.current = 1; pan.current.set(0, 0); }
    else drag.current = null;
  }, [inspecting]);
  useEffect(() => {
    if (!inspecting) return undefined;
    const canvas = gl.domElement;
    // Own the whole canvas while inspecting. Raycasting only the model loses
    // the drag target when a thin object (such as the board) turns edge-on.
    const start = event => {
      if (event.button !== 0 || drag.current) return;
      event.preventDefault(); event.stopImmediatePropagation();
      if (controls) controls.enabled = false;
      drag.current = { pointerId: event.pointerId, x: event.clientX, y: event.clientY, pan: wheelMode === 'zoom' && event.shiftKey };
      canvas.setPointerCapture(event.pointerId);
      canvas.dataset.inspectionDragging = 'true';
    };
    const move = event => {
      const previous = drag.current;
      if (!previous || previous.pointerId !== event.pointerId) return;
      event.preventDefault(); event.stopImmediatePropagation();
      if (previous.pan) {
        const unitsPerPixel = 2 * Math.tan(THREE.MathUtils.degToRad(camera.fov / 2)) * framedDistance / zoom.current / size.height;
        pan.current.x += (event.clientX - previous.x) * unitsPerPixel;
        pan.current.y -= (event.clientY - previous.y) * unitsPerPixel;
      } else rotateBoard(orientation.current, event.clientX - previous.x, event.clientY - previous.y, Math.min(size.width, size.height));
      previous.x = event.clientX; previous.y = event.clientY;
    };
    const end = event => {
      const previous = drag.current;
      if (!previous || (event?.pointerId !== undefined && previous.pointerId !== event.pointerId)) return;
      drag.current = null;
      delete canvas.dataset.inspectionDragging;
      if (canvas.hasPointerCapture(previous.pointerId)) canvas.releasePointerCapture(previous.pointerId);
    };
    const blockClick = event => event.stopImmediatePropagation();
    const blur = () => end();
    const turn = event => {
      if (event.ctrlKey) return;
      event.preventDefault(); event.stopImmediatePropagation();
      const pixels = event.deltaY * (event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? 300 : 1);
      if (wheelMode === 'zoom') {
        zoom.current = THREE.MathUtils.clamp(zoom.current * Math.exp(-pixels * 0.002), 1, 3);
        if (zoom.current === 1) pan.current.set(0, 0);
        return;
      }
      rotateBoard(orientation.current, THREE.MathUtils.clamp(pixels, -180, 180), 0, Math.min(size.width, size.height));
    };
    canvas.addEventListener('pointerdown', start, true);
    canvas.addEventListener('pointermove', move, true);
    canvas.addEventListener('click', blockClick, true);
    canvas.addEventListener('lostpointercapture', end);
    canvas.addEventListener('wheel', turn, { passive: false, capture: true });
    window.addEventListener('pointerup', end, true);
    window.addEventListener('pointercancel', end, true);
    window.addEventListener('blur', blur);
    return () => {
      end();
      canvas.removeEventListener('pointerdown', start, true);
      canvas.removeEventListener('pointermove', move, true);
      canvas.removeEventListener('click', blockClick, true);
      canvas.removeEventListener('lostpointercapture', end);
      canvas.removeEventListener('wheel', turn, true);
      window.removeEventListener('pointerup', end, true);
      window.removeEventListener('pointercancel', end, true);
      window.removeEventListener('blur', blur);
    };
  }, [gl, inspecting, size.width, size.height, wheelMode, camera, controls, framedDistance]);

  useFrame((_, delta) => {
    if (!ref.current) return;
    const alpha = reducedMotion ? 1 : 1 - Math.exp(-delta * 8);
    if (inspecting) {
      const narrow = size.width < 600;
      scratch.position.set(framing ? pan.current.x : distance * 0.033, framing ? pan.current.y : narrow ? distance * 0.088 : 0.01,
        framing ? -framedDistance / zoom.current : -distance * (narrow ? 1.28 : 1))
        .applyQuaternion(camera.quaternion).add(camera.position);
      scratch.rotation.copy(camera.quaternion).multiply(orientation.current);
      // A picked-up object can live inside a moving drawer. Convert the camera
      // pose into that parent's local space, keeping the object in the hand.
      const parent = ref.current.parent;
      parent.updateWorldMatrix(true, false);
      parent.worldToLocal(scratch.position);
      parent.getWorldQuaternion(scratch.parent).invert();
      scratch.rotation.premultiply(scratch.parent);
    } else {
      scratch.position.copy(homePosition); scratch.rotation.copy(homeRotation);
    }
    ref.current.position.lerp(scratch.position, alpha);
    ref.current.quaternion.slerp(scratch.rotation, alpha);
  });
  return { ref, handlers: {
    onClick: event => { event.stopPropagation(); if (!inspecting && event.delta <= 5) onInspect(true); },
  } };
}
