import React from 'react';

export default function Backpack({ hasKey, inspecting, onStore, onInspect }) {
  if (!hasKey && !inspecting) return null;
  return <aside className='backpack' aria-label='Backpack' onClick={event => event.stopPropagation()}>
    <span>Backpack</span>
    <button className={`backpack-slot ${inspecting && !hasKey ? 'awaiting-key' : ''}`} onClick={inspecting ? onStore : onInspect}
      aria-label={inspecting ? 'Put Rusty Lake key in backpack' : 'Inspect Rusty Lake key'} title={inspecting ? 'Put key away' : 'Rusty Lake key · Click to inspect'}>
      <svg viewBox='0 0 64 80' aria-hidden='true'><circle cx='32' cy='20' r='13' fill='none' stroke='currentColor' strokeWidth='5' />
        <path d='M32 34v35h12v-8H32m0-10h10' fill='none' stroke='currentColor' strokeWidth='5' strokeLinejoin='round' />
        <rect className='backpack-cube' x='27' y='15' width='10' height='10' fill='#292c2b' /></svg>
      {inspecting && !hasKey && <span className='backpack-add'>+</span>}
    </button>
    <small>{inspecting ? 'Put away' : 'Rusty Lake key'}</small>
  </aside>;
}
