import { useCallback, useEffect, useRef } from 'react';

export default function useRoomAudio() {
  const audio = useRef();
  useEffect(() => () => { audio.current?.close().catch(() => {}); }, []);
  return useCallback(kind => {
    const Audio = window.AudioContext || window.webkitAudioContext;
    if (!Audio) return;
    if (!audio.current) audio.current = new Audio();
    const ctx = audio.current;
    ctx.resume().catch(() => {});
    const start = ctx.currentTime;
    const click = (delay, frequency, duration, volume, noise = false) => {
      const gain = ctx.createGain(), filter = ctx.createBiquadFilter();
      filter.type = noise ? 'bandpass' : 'lowpass'; filter.frequency.value = frequency; filter.Q.value = noise ? 1.4 : .7;
      let source;
      if (noise) {
        const buffer = ctx.createBuffer(1, Math.ceil(ctx.sampleRate * duration), ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
        source = ctx.createBufferSource(); source.buffer = buffer;
      } else {
        source = ctx.createOscillator(); source.type = 'triangle'; source.frequency.setValueAtTime(frequency, start + delay);
        source.frequency.exponentialRampToValueAtTime(frequency * .45, start + delay + duration);
      }
      gain.gain.setValueAtTime(volume, start + delay);
      gain.gain.exponentialRampToValueAtTime(.0001, start + delay + duration);
      source.connect(filter); filter.connect(gain); gain.connect(ctx.destination);
      source.start(start + delay); source.stop(start + delay + duration);
      source.onended = () => { source.disconnect(); filter.disconnect(); gain.disconnect(); };
    };
    if (kind === 'lamp') { click(0, 3100, .034, .18, true); click(.033, 1450, .025, .08, true); }
    if (kind === 'locked') { click(0, 380, .07, .13); click(.105, 1700, .09, .13, true); click(.19, 230, .08, .12); }
    if (kind === 'unlock') { click(0, 1400, .045, .14, true); click(.09, 950, .22, .065); click(.12, 2800, .65, .06, true); }
    if (kind === 'collect') { click(0, 1300, .1, .045); click(.06, 1800, .14, .035); }
  }, []);
}
