// Drawn at twice the screen's design resolution so type remains crisp in close-up.
// Only the two photographic backgrounds are sampled from the supplied reference;
// all dashboard text, icons, charts and cards are rendered independently.
export const dashboardSize = [1600, 920];
const ink = '#142442';
const muted = '#657189';
const blue = '#397ef4';
const green = '#60c5a0';
const amber = '#ffb849';
const purple = '#9950ee';

export function drawDashboard(canvas, photo) {
  const ctx = canvas.getContext('2d');
  ctx.setTransform(2, 0, 0, 2, 0, 0);
  const text = (value, x, y, size = 16, color = ink, weight = 400, align = 'left') => {
    ctx.font = `${weight} ${size}px Arial, sans-serif`;
    ctx.fillStyle = color; ctx.textAlign = align; ctx.fillText(value, x, y);
  };
  const box = (x, y, w, h, fill = '#fff', radius = 10, stroke) => {
    ctx.beginPath(); ctx.roundRect(x, y, w, h, radius); ctx.fillStyle = fill; ctx.fill();
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = 1; ctx.stroke(); }
  };
  const line = (points, color = muted, width = 2) => {
    ctx.beginPath(); points.forEach(([x, y], i) => i ? ctx.lineTo(x, y) : ctx.moveTo(x, y));
    ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
  };
  const circle = (x, y, radius, color, stroke = false) => {
    ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2);
    if (stroke) { ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.stroke(); }
    else { ctx.fillStyle = color; ctx.fill(); }
  };
  const icon = (kind, x, y, color = blue, size = 28) => {
    ctx.save(); ctx.translate(x, y); ctx.scale(size / 28, size / 28);
    ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = 2; ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    if (kind === 'file') {
      line([[5, 2], [17, 2], [23, 8], [23, 26], [5, 26], [5, 2]], color);
      line([[16, 2], [16, 9], [23, 9]], color);
      [13, 18, 22].forEach(y0 => line([[9, y0], [19, y0]], color));
    } else if (kind === 'chat') {
      line([[3, 3], [25, 3], [25, 21], [11, 21], [3, 26], [3, 3]], color);
      [9, 14].forEach(y0 => line([[8, y0], [20, y0]], color));
    } else if (kind === 'grid' || kind === 'table') {
      if (kind === 'grid') [3, 16].forEach(a => [3, 16].forEach(b => box(a, b, 9, 9, '#ffffff00', 2, color)));
      else { box(3, 3, 22, 22, '#ffffff00', 1, color); [10, 17].forEach(n => { line([[n, 3], [n, 25]], color); line([[3, n], [25, n]], color); }); }
    } else if (kind === 'globe') {
      circle(14, 14, 12, color, true); ctx.beginPath(); ctx.ellipse(14, 14, 5, 12, 0, 0, 7); ctx.stroke(); line([[2, 14], [26, 14]], color);
    } else if (kind === 'calendar') {
      box(3, 5, 22, 21, '#ffffff00', 2, color); line([[3, 11], [25, 11]], color); [9, 20].forEach(n => line([[n, 2], [n, 8]], color, 3));
    } else if (kind === 'network' || kind === 'people') {
      const nodes = kind === 'network' ? [[14, 4], [4, 23], [24, 23]] : [[7, 7], [21, 7], [14, 22]];
      line([...nodes, nodes[0]], color); nodes.forEach(([a, b]) => { circle(a, b, 3, '#fff'); circle(a, b, 3, color, true); });
    } else if (kind === 'chart') {
      box(2, 3, 24, 22, '#ffffff00', 2, color); line([[5, 20], [11, 12], [16, 16], [23, 7]], color);
    } else if (kind === 'camera') {
      box(2, 6, 24, 19, '#ffffff00', 3, color); circle(14, 15, 5, color, true); line([[8, 6], [10, 2], [18, 2], [20, 6]], color);
    } else if (kind === 'mountain') {
      line([[1, 24], [11, 5], [17, 16], [21, 10], [28, 24], [1, 24]], color); line([[7, 13], [11, 16], [14, 12]], color);
    } else if (kind === 'database') {
      [5, 13, 22].forEach(n => { ctx.beginPath(); ctx.ellipse(14, n, 10, 4, 0, 0, 7); ctx.stroke(); }); line([[4, 5], [4, 22]], color); line([[24, 5], [24, 22]], color);
    } else if (kind === 'bulb') {
      circle(14, 11, 8, color, true); line([[9, 18], [11, 25], [17, 25], [19, 18]], color);
    } else {
      line([[7, 2], [7, 26]], color); line([[2, 2], [2, 11], [12, 11], [12, 2]], color); line([[23, 2], [18, 14], [23, 14], [23, 26]], color);
    }
    ctx.restore();
  };
  const pill = (label, x, y, w, color, fill, size = 15) => {
    box(x, y, w, 30, fill, 15); text(label, x + w / 2, y + 20, size, color, 400, 'center');
  };
  const panel = (title, subtitle, x, y, w, h) => {
    box(x, y, w, h, '#fff', 11, '#e9edf3');
    text(title, x + 20, y + 32, 21, ink, 700); text(subtitle, x + 20, y + 57, 15, muted);
  };

  ctx.fillStyle = '#fafcfe'; ctx.fillRect(0, 0, 1600, 920);
  ctx.fillStyle = '#193a59'; ctx.fillRect(0, 0, 1600, 204);
  if (photo) ctx.drawImage(photo, 435, 0, 480, 180, 0, 0, 1600, 204);
  const shade = ctx.createLinearGradient(0, 0, 1600, 0);
  shade.addColorStop(0, 'rgba(5,20,39,.88)'); shade.addColorStop(.6, 'rgba(10,29,49,.12)'); shade.addColorStop(1, 'rgba(9,24,45,.3)');
  ctx.fillStyle = shade; ctx.fillRect(0, 0, 1600, 204);
  text('Hi, I’m', 46, 72, 49, '#fff', 700); text('Marco', 208, 72, 49, '#92c4ff', 700);
  text('Data Science   ·   AI Systems   ·   Research   ·   Building', 48, 111, 19, '#f3f6ff', 600);
  text('I use data and AI to study complex systems and build tools', 48, 153, 17, '#f5f7fc');
  text('that help people make better decisions.', 48, 179, 17, '#f5f7fc');
  box(1128, 27, 424, 147, 'rgba(10,23,43,.66)', 12);
  text('“From data to real-world impact.”', 1340, 74, 21, '#fff', 400, 'center');
  line([[1325, 99], [1355, 99]], '#bbc6d4', 1);
  [['mountain', 'Snowboarding', 1156], ['camera', 'Photography', 1298], ['food', 'Food & Travel', 1433]].forEach(([kind, label, x]) => {
    icon(kind, x, 131, '#f3f6ff', 18); text(label, x + 25, 145, 12, '#f3f6ff');
  });

  const metrics = [
    ['file', 'Data Analyzed', '100M+', ['rows of data'], blue, '#edf4ff'],
    ['chat', 'Datasets Interacted With', '80+', ['real world data'], '#893be5', '#f5f0ff'],
    ['grid', 'Projects Shipped', '10+', ['research + product + class'], '#219874', '#edf9f5'],
    ['globe', 'Domains', '5', ['social · supply chain · healthcare', 'retail · enterprise AI'], '#bc651b', '#fff7ef'],
    ['calendar', 'Years Intern', '1', ['of data science experience'], '#d20b3d', '#fff1f5'],
  ];
  metrics.forEach(([kind, label, value, copy, color, fill], i) => {
    const x = 18 + i * 315;
    box(x, 221, 304, 116, fill, 10); box(x + 16, 238, 51, 51, `${color}0d`, 9);
    icon(kind, x + 27, 249, color, 30);
    text(label, x + 85, 251, 16, ink, 700); text(value, x + 85, 288, 35, ink, 700);
    copy.forEach((row, j) => text(row, x + 85, 310 + j * 16, 13, muted));
  });

  panel('My Work by Domain', 'Different data. Real-world problems.', 18, 353, 530, 271);
  const domains = [['Social Computing', 35, blue], ['Supply Chain', 25, amber], ['Healthcare', 15, green], ['Retail', 15, '#aa7af0'], ['Enterprise AI', 10, '#b9c4d2']];
  let angle = -Math.PI / 2;
  domains.forEach(([label, value, color], i) => {
    ctx.beginPath(); ctx.arc(148, 511, 77, angle, angle + value / 100 * Math.PI * 2); ctx.strokeStyle = color; ctx.lineWidth = 44; ctx.stroke(); angle += value / 100 * Math.PI * 2;
    box(280, 445 + i * 33, 16, 16, color, 4); text(label, 313, 458 + i * 33, 14); text(`${value}%`, 524, 458 + i * 33, 14, ink, 400, 'right');
  });
  text('100%', 148, 519, 22, ink, 500, 'center');

  panel('Methods & Tools', 'Techniques and tools I use across projects.', 564, 353, 498, 271);
  const skillRows = [
    [['Python', 99], ['SQL', 80], ['Machine Learning', 174]],
    [['NLP', 81], ['LLMs & AI Agents', 175], ['Data Engineering', 177]],
    [['Experimentation', 177], ['Data Visualization', 186]],
    [['Cloud (AWS)', 141], ['FastAPI', 103], ['PostgreSQL', 139]],
    [['Research Methods', 184], ['A/B Testing', 132], ['Analytics', 113]],
  ];
  skillRows.forEach((row, i) => {
    let x = 584;
    row.forEach(([label, w], j) => { const colors = label === 'LLMs & AI Agents' || label === 'A/B Testing' ? ['#6750a7', '#f0eaff'] : (i + j) % 3 === 2 ? ['#247e6c', '#e9f7f2'] : ['#306dbf', '#eaf2ff']; pill(`› ${label}`, x, 429 + i * 36, w, ...colors); x += w + 9; });
  });

  panel('Types of Data I’ve Worked With', 'From text and networks to enterprise data.', 1078, 353, 504, 271);
  [['file', 'Text Data', 1, blue], ['network', 'Network Data', .63, amber], ['table', 'Tabular Data', .45, green], ['chart', 'Time Series', .3, '#b5a0f4'], ['camera', 'Multimodal', .15, '#b9c4d2']].forEach(([kind, label, amount, color], i) => {
    const y = 429 + i * 37;
    icon(kind, 1101, y + 2, muted, 20); text(label, 1139, y + 18, 14);
    box(1279, y, 278, 21, '#f1f4f8', 3); box(1279, y, 278 * amount, 21, color, 3);
    if (i === 4) text('(text/image/video)', 1139, y + 35, 12);
  });

  panel('My Journey', 'From learning to real-world impact.', 18, 640, 584, 262);
  line([[85, 755], [519, 755]], '#dde3ed', 2);
  const journey = [
    ['2023', 'Datathon', 'Healthcare prediction', '(XGBoost, ~98%)', 'Prediction', blue, '#edf4ff', 108],
    ['2024', 'Research', 'NLP & social data', '(Code & Cognition Lab)', 'NLP', green, '#eaf8f3', 82],
    ['2025', 'Human-AI', 'Community Notes', '(Saveski Lab)', 'Human-AI Systems', amber, '#fff4e9', 132],
    ['2026', 'Enterprise', 'Supply Chain & AI', '(Molex GSOP&E)', 'Operations', purple, '#f2ebff', 116],
  ];
  journey.forEach(([year, title, a, b, tag, color, fill, w], i) => {
    const x = 87 + i * 144;
    if (i < 3) text('⟶', x + 72, 760, 23, '#b7c1d1', 400, 'center');
    text(year, x, 734, 18, color, 700, 'center'); circle(x, 755, 10, '#fff'); circle(x, 755, 8, color);
    text(title, x, 791, 16, ink, 700, 'center'); text(a, x, 817, 12, muted, 400, 'center'); text(b, x, 836, 12, muted, 400, 'center');
    pill(tag, x - w / 2, 854, w, i === 2 ? '#b97222' : color, fill, 12);
  });

  panel('Featured Projects', 'A few recent highlights.', 618, 640, 505, 262);
  const projects = [
    ['chat', 'Community Notes Analysis', '1.1M+ notes · 105M+ edges', 'Studied human feedback dynamics and diversity in', 'collaborative fact-checking.', 'NLP', '#eaf2ff', '#397ef4', 70],
    ['chart', 'AI Observability Bot', 'BeeAI · Splunk · OpenTelemetry', 'Built an AI customer service agent focused on', 'observability and security for regulated industries.', 'Agentic AI', '#e8f7f1', '#278573', 110],
    ['camera', 'YOLO-World Reproduction', 'Computer Vision', 'Reproduced open-vocabulary object detection with', 'custom evaluation.', 'Computer Vision', '#f1ebff', '#7851bd', 133],
  ];
  projects.forEach(([kind, title, meta, a, b, tag, fill, color, w], i) => {
    const y = 709 + i * 62;
    box(630, y, 481, 58, '#fff', 8, '#e9edf3'); box(640, y + 10, 40, 38, '#eaf2ff', 8); icon(kind, 651, y + 20, blue, 20);
    text(title, 692, y + 17, 14, ink, 600); text(meta, 692, y + 31, 11, muted);
    text(a, 692, y + 44, 11, muted); text(b, 692, y + 56, 11, muted);
    box(1099 - w, y + 5, w, 20, fill, 10); text(tag, 1099 - w / 2, y + 19, 10, color, 400, 'center');
  });

  panel('Currently Exploring', 'ML for operations and decision support.', 1139, 640, 443, 262);
  ctx.save(); ctx.beginPath(); ctx.roundRect(1153, 712, 415, 139, 9); ctx.clip();
  ctx.fillStyle = '#324c68'; ctx.fillRect(1153, 712, 415, 139);
  if (photo) ctx.drawImage(photo, 924, 645, 332, 65, 1153, 712, 415, 139);
  const cardShade = ctx.createLinearGradient(0, 712, 0, 851); cardShade.addColorStop(0, 'rgba(10,22,42,.04)'); cardShade.addColorStop(1, 'rgba(8,22,43,.98)');
  ctx.fillStyle = cardShade; ctx.fillRect(1153, 712, 415, 139); ctx.restore();
  text('ML for Operations', 1174, 758, 24, '#fff', 700); text('From data → models → decisions.', 1174, 781, 15, '#f6f8ff');
  text('Turning messy real-world data into', 1174, 808, 14, '#fff'); text('systems people can actually use.', 1174, 827, 14, '#fff');
  [['database', 'Data', 'Real-world complexity', blue], ['bulb', 'Models', 'Practical & reliable', '#ce7a25'], ['people', 'Decisions', 'People in the loop', '#2e9c78']].forEach(([kind, title, subtitle, color], i) => {
    const x = 1154 + i * 139;
    box(x, 863, 29, 29, `${color}0d`, 5); icon(kind, x + 6, 869, color, 18);
    text(title, x + 37, 875, 12, ink, 700); text(subtitle, x + 37, 890, 9, muted);
  });
}
