// Reference 75% layout, measured in standard key units.
export const keyUnit = 0.0545;
export const keyboardColors = { white: '#d9dde3', purple: '#8b86bc', blue: '#91b3cd' };
const key = (label, code, width = 1, color = 'white') => ({ label, code, width, color });
const letters = text => [...text].map(label => key(label, `Key${label}`));
const rows = [
  [key('~', 'Backquote'), ...[...'1234567890'].map(label => key(label, `Digit${label}`)), key('−', 'Minus'), key('= +', 'Equal'), key('←', 'Backspace', 2, 'purple')],
  [key('Tab ⇥', 'Tab', 1.5, 'purple'), ...letters('QWERTYUIOP'), key('[ {', 'BracketLeft'), key('] }', 'BracketRight'), key('\\ |', 'Backslash', 1.5)],
  [key('CapsLk', 'CapsLock', 1.75, 'purple'), ...letters('ASDFGHJKL'), key('; :', 'Semicolon'), key("' \"", 'Quote'), key('Enter ↵', 'Enter', 2.25, 'blue')],
  [key('↑ Shift', 'ShiftLeft', 2.25, 'purple'), ...letters('ZXCVBNM'), key(', <', 'Comma'), key('. >', 'Period'), key('/ ?', 'Slash'), key('↑ Shift', 'ShiftRight', 1.75, 'purple')],
  [key('Ctrl', 'ControlLeft', 1.25, 'purple'), key('Win', 'MetaLeft', 1.25, 'purple'), key('Alt', 'AltLeft', 1.25, 'purple'), key('━', 'Space', 6.25, 'blue'), key('Alt', 'AltRight', 1, 'purple'), key('Fn', 'Fn', 1, 'purple'), key('Ctrl', 'ControlRight', 1, 'purple')],
];
const place = (item, offset, z) => ({ ...item, x: -0.447 + (offset + item.width / 2) * keyUnit, z });
export const keyboardKeys = [
  place(key('Esc', 'Escape', 1, 'blue'), 0, -0.159),
  ...Array.from({ length: 12 }, (_, i) => place(key(`F${i + 1}`, `F${i + 1}`, 1, i >= 4 && i < 8 ? 'purple' : 'white'), 1.25 + i + Math.floor(i / 4) * 0.25, -0.159)),
  place(key('Del', 'Delete', 1, 'purple'), 13.8, -0.159),
  ...rows.flatMap((row, r) => {
    let offset = 0;
    return row.map(item => { const placed = place(item, offset, -0.086 + r * keyUnit); offset += item.width; return placed; });
  }),
  ...['Home', 'PgUp', 'PgDn', 'End'].map((label, row) => place(key(label, ['Home', 'PageUp', 'PageDown', 'End'][row], 1, 'purple'), 15.35, -0.086 + row * keyUnit)),
  place(key('↑', 'ArrowUp', 1, 'purple'), 14.15, -0.086 + keyUnit * 3.12),
  ...['←', '↓', '→'].map((label, i) => place(key(label, ['ArrowLeft', 'ArrowDown', 'ArrowRight'][i], 1, 'purple'), 13.15 + i, -0.086 + keyUnit * 4.12)),
];
