import React from 'react';
import { RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
const oak = '#c3a17b';
const ivory = '#e7e2d7';
const metal = '#a5a5a0';

export function Box({ args, position, color = oak, radius = 0.015, map, ...props }) {
  // A bevel must fit the smallest dimension, especially on thin surfaces.
  const bevel = Math.min(radius, Math.min(...args) / 2 - 0.0001);
  return <RoundedBox args={args} radius={Math.max(0.0001, bevel)} smoothness={2}
    position={position} castShadow receiveShadow {...props}>
    <meshStandardMaterial color={color} map={map} roughness={0.78} />
  </RoundedBox>;
}

export function Cylinder({ position, args, color = ivory, ...props }) {
  return <mesh position={position} castShadow receiveShadow {...props}>
    <cylinderGeometry args={args} /><meshStandardMaterial color={color} roughness={0.65} />
  </mesh>;
}

export function Ellipsoid({ position, scale, color, ...props }) {
  return <mesh position={position} scale={scale} castShadow receiveShadow {...props}>
    <sphereGeometry args={[1, 20, 14]} /><meshStandardMaterial color={color} roughness={0.85} />
  </mesh>;
}

export function Rod({ from, to, radius = 0.025, color = metal }) {
  const start = new THREE.Vector3(...from);
  const end = new THREE.Vector3(...to);
  const delta = end.clone().sub(start);
  const rotation = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), delta.clone().normalize());
  return <Cylinder args={[radius, radius, delta.length(), 10]} color={color}
    position={start.add(end).multiplyScalar(0.5)} quaternion={rotation} />;
}
