function makeTexture(kind) {
  const canvas = document.createElement('canvas');
  canvas.width = 512; canvas.height = 512;
  const ctx = canvas.getContext('2d');
  let seed = 1847;
  const random = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  if (kind === 'wood' || kind === 'rug') {
    ctx.fillStyle = kind === 'wood' ? '#ebd5b7' : '#ddd4bf'; ctx.fillRect(0, 0, 512, 512);
    for (let i = 0; i < (kind === 'wood' ? 950 : 25000); i++) {
      ctx.fillStyle = `rgba(91,66,43,${random() * (kind === 'wood' ? 0.07 : 0.18)})`;
      ctx.fillRect(random() * 512, random() * 512, kind === 'wood' ? random() * 180 + 15 : 1.5, kind === 'wood' ? 0.7 : 1.5);
    }
  } else if (kind === 'screen' || kind === 'art') {
    const gradient = ctx.createLinearGradient(0, 0, 0, 512);
    gradient.addColorStop(0, '#c8d5c5'); gradient.addColorStop(0.5, '#82a3a0'); gradient.addColorStop(1, '#3d6566');
    ctx.fillStyle = gradient; ctx.fillRect(0, 0, 512, 512);
    ctx.fillStyle = '#e7d3a3'; ctx.beginPath(); ctx.arc(362, 132, 47, 0, Math.PI * 2); ctx.fill();
    for (let i = 0; i < 4; i++) {
      ctx.fillStyle = ['#9cb6a6', '#779b8c', '#597e78', '#355e61'][i];
      ctx.beginPath(); ctx.moveTo(0, 270 + i * 55);
      ctx.bezierCurveTo(170, 150 + i * 60, 310, 430 - i * 22, 512, 245 + i * 65);
      ctx.lineTo(512, 512); ctx.lineTo(0, 512); ctx.fill();
    }
    if (kind === 'screen') {
      ctx.fillStyle = 'rgba(245,243,226,.8)'; ctx.font = '38px Georgia'; ctx.textAlign = 'center'; ctx.fillText('a quieter kind of work.', 256, 100);
      ctx.fillStyle = 'rgba(255,255,255,.25)'; ctx.fillRect(140, 475, 232, 23);
      for (let i = 0; i < 10; i++) { ctx.fillStyle = ['#dfb583', '#7d9893', '#eee7d3'][i % 3]; ctx.fillRect(151 + i * 22, 479, 14, 14); }
    }
  } else if (kind === 'calendar') {
    ctx.fillStyle = '#f6f1e6'; ctx.fillRect(0, 0, 512, 512);
    ctx.fillStyle = '#574d42'; ctx.font = '38px Georgia'; ctx.textAlign = 'center'; ctx.fillText('SEPTEMBER', 256, 102);
    ctx.font = '25px sans-serif';
    for (let i = 0; i < 30; i++) ctx.fillText(String(i + 1), 61 + (i % 7) * 65, 196 + Math.floor(i / 7) * 58);
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

