import React, { useEffect, useMemo, useRef } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import * as THREE from 'three';

export function WindowSky({ night, reducedMotion }) {
  const material = useRef();
  const sunset = useMemo(() => {
    const canvas = document.createElement('canvas'); canvas.width = 64; canvas.height = 256;
    const ctx = canvas.getContext('2d'), gradient = ctx.createLinearGradient(0, 0, 0, 256);
    gradient.addColorStop(0, '#55527f'); gradient.addColorStop(.4, '#c88891'); gradient.addColorStop(.7, '#ffb377'); gradient.addColorStop(1, '#ffc477');
    ctx.fillStyle = gradient; ctx.fillRect(0, 0, 64, 256);
    const map = new THREE.CanvasTexture(canvas); map.colorSpace = THREE.SRGBColorSpace; return map;
  }, []);
  useEffect(() => () => sunset.dispose(), [sunset]);
  useFrame((_, dt) => { if (material.current) material.current.opacity = reducedMotion ? Number(night) : THREE.MathUtils.damp(material.current.opacity, Number(night), 3, dt); });
  return <mesh position={[0, 0, .061]} raycast={() => null}><planeGeometry args={[.77, 1.5]} />
    <meshBasicMaterial ref={material} map={sunset} transparent opacity={0} depthWrite={false} toneMapped={false} /></mesh>;
}

export default function RoomLighting({ night, reducedMotion }) {
  const ambient = useRef(), hemisphere = useRef(), sun = useRef(), evening = useRef(), glow = useRef(), patch = useRef();
  const progress = useRef(0);
  const { scene } = useThree();
  const colors = useMemo(() => [new THREE.Color('#d3cec3'), new THREE.Color('#222637')], []);
  const target = useMemo(() => { const object = new THREE.Object3D(); object.position.set(.35, .2, .8); return object; }, []);
  const stripes = useMemo(() => {
    const canvas = document.createElement('canvas'); canvas.width = 256; canvas.height = 256;
    const ctx = canvas.getContext('2d'); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, 256, 256);
    ctx.fillStyle = '#111'; for (let y = 15; y < 256; y += 36) ctx.fillRect(0, y, 256, 9);
    ctx.fillRect(121, 0, 14, 256);
    const map = new THREE.CanvasTexture(canvas); return map;
  }, []);
  useEffect(() => () => stripes.dispose(), [stripes]);
  useFrame((_, dt) => {
    const t = progress.current = reducedMotion ? Number(night) : THREE.MathUtils.damp(progress.current, Number(night), 3, dt);
    scene.background?.copy(colors[0]).lerp(colors[1], t);
    ambient.current.intensity = THREE.MathUtils.lerp(.75, .12, t);
    hemisphere.current.intensity = THREE.MathUtils.lerp(1.15, .36, t);
    sun.current.intensity = THREE.MathUtils.lerp(2.5, .12, t);
    evening.current.intensity = t * 32; glow.current.intensity = t * 1.8;
    patch.current.opacity = t * .12;
  });
  return <>
    <color attach='background' args={['#d3cec3']} />
    <ambientLight ref={ambient} intensity={.75} color='#fff5e6' />
    <hemisphereLight ref={hemisphere} args={['#bdc9ef', '#977269', 1.15]} />
    <directionalLight ref={sun} castShadow position={[-3.5, 6.5, 3]} intensity={2.5} color='#fff0d7'
      shadow-mapSize={[2048, 2048]} shadow-camera-left={-5} shadow-camera-right={5} shadow-camera-top={5} shadow-camera-bottom={-5}
      shadow-normalBias={.018} shadow-bias={-.00015} />
    <primitive object={target} />
    <spotLight ref={evening} target={target} position={[-2.39, 2.91, -2.12]} color='#ff995b' intensity={0} distance={10}
      angle={.65} penumbra={.5} decay={2} map={stripes} castShadow shadow-mapSize={[1024, 1024]} shadow-bias={-.0001} />
    <pointLight ref={glow} position={[-2.32, 2.45, -1.98]} color='#ff9e74' intensity={0} distance={4} />
    <mesh position={[-1.27, .027, .28]} rotation={[-Math.PI / 2, 0, -.55]} raycast={() => null}>
      <planeGeometry args={[1.6, 2.7]} /><meshBasicMaterial ref={patch} color='#ffaf69' alphaMap={stripes} transparent opacity={0} depthWrite={false} toneMapped={false} />
    </mesh>
  </>;
}
