import React, { useEffect, useMemo } from 'react';
import { useLoader, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { wallObjects } from './layout.mjs';
import useInspection from './useInspection';

const mount = wallObjects.find(item => item.name === 'snowboard');
const wallPosition = new THREE.Vector3(2.96, mount.y, mount.z);
const wallRotation = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), -Math.PI / 2);
const imageScale = 2.06 / 588;

function RackBlock({ position, size, color = '#39423e' }) {
  return <mesh position={position} castShadow receiveShadow>
    <boxGeometry args={size} /><meshStandardMaterial color={color} roughness={0.68} />
  </mesh>;
}

export function SnowboardRack() {
  return <group name='Permanent snowboard wall rack' position={wallPosition} quaternion={wallRotation}>
    {[-0.62, 0.62].map(y => <group key={y} position={[0, y, 0]}>
      <RackBlock position={[0, 0, 0]} size={[0.22, 0.16, 0.04]} color='#9f805a' />
      <RackBlock position={[0, -0.028, 0.046]} size={[0.39, 0.035, 0.065]} />
      {[-0.188, 0.188].map(x => <group key={x}>
        <RackBlock position={[x, -0.01, 0.081]} size={[0.026, 0.07, 0.09]} />
        <RackBlock position={[x, 0.023, 0.117]} size={[0.027, 0.025, 0.027]} color='#242c28' />
      </group>)}
      {[-0.075, 0.075].map(x => <mesh key={x} position={[x, 0.045, 0.023]} rotation={[Math.PI / 2, 0, 0]}>
        <cylinderGeometry args={[0.011, 0.011, 0.008, 12]} /><meshStandardMaterial color='#a7a99d' metalness={0.75} roughness={0.3} />
      </mesh>)}
    </group>)}
  </group>;
}

function makeOutline() {
  // Trace the left/front board in source-image coordinates. The same image is
  // sampled directly through UVs, preserving its art and lettering unchanged.
  const shape = new THREE.Shape();
  const point = (x, y) => [(x - 57.5) * imageScale, (294 - y) * imageScale];
  shape.moveTo(...point(57.5, 2));
  shape.bezierCurveTo(...point(97, 2), ...point(113, 33), ...point(113, 65));
  shape.bezierCurveTo(...point(111, 140), ...point(104, 211), ...point(104, 294));
  shape.bezierCurveTo(...point(104, 374), ...point(110, 447), ...point(113, 490));
  shape.bezierCurveTo(...point(112, 551), ...point(96, 584), ...point(57.5, 586));
  shape.bezierCurveTo(...point(22, 584), ...point(3, 551), ...point(2, 490));
  shape.bezierCurveTo(...point(5, 447), ...point(11, 374), ...point(11, 294));
  shape.bezierCurveTo(...point(11, 211), ...point(4, 140), ...point(2, 65));
  shape.bezierCurveTo(...point(2, 33), ...point(18, 2), ...point(57.5, 2));
  shape.closePath();
  return shape;
}

function makeFace(outline, side) {
  const geometry = new THREE.ShapeGeometry(outline, 40);
  const positions = geometry.attributes.position;
  const uv = geometry.attributes.uv;
  for (let i = 0; i < positions.count; i++) {
    const pixelX = positions.getX(i) / imageScale;
    // Left image: front. Right image: base, readable when viewed from behind.
    uv.setXY(i, (side === 'front' ? pixelX + 57.5 : pixelX + 178.5) / 236,
      positions.getY(i) / (588 * imageScale) + 0.5);
  }
  uv.needsUpdate = true;
  return geometry;
}

export default function Snowboard({ inspecting, onInspect, reducedMotion }) {
  const { ref, handlers } = useInspection({ inspecting, onInspect, reducedMotion, homePosition: wallPosition, homeRotation: wallRotation });
  const { gl } = useThree();
  const texture = useLoader(THREE.TextureLoader, `${process.env.PUBLIC_URL}/assets/images/snowboard-reference.png`);
  const geometry = useMemo(() => {
    const outline = makeOutline();
    return {
      body: new THREE.ExtrudeGeometry(outline, { depth: 0.032, bevelEnabled: true,
        bevelSize: 0.002, bevelThickness: 0.002, bevelSegments: 3, curveSegments: 40 }),
      front: makeFace(outline, 'front'), back: makeFace(outline, 'back'),
    };
  }, []);

  useEffect(() => {
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = Math.min(8, gl.capabilities.getMaxAnisotropy());
    texture.needsUpdate = true;
  }, [texture, gl]);
  useEffect(() => () => Object.values(geometry).forEach(item => item.dispose()), [geometry]);
  return <group ref={ref} name='Inspect snowboard' position={wallPosition} quaternion={wallRotation} {...handlers}>
    <mesh geometry={geometry.body} position={[0, 0, 0.083]} castShadow={!inspecting} receiveShadow={!inspecting}>
      <meshStandardMaterial color='#d5d638' metalness={0.1} roughness={0.4} />
    </mesh>
    <mesh geometry={geometry.front} position={[0, 0, 0.118]} receiveShadow={!inspecting}>
      <meshStandardMaterial map={texture} roughness={0.6} />
    </mesh>
    <mesh geometry={geometry.back} position={[0, 0, 0.08]} rotation={[0, Math.PI, 0]} receiveShadow={!inspecting}>
      <meshStandardMaterial map={texture} roughness={0.56} />
    </mesh>
  </group>;
}
