export const playableCodes = [...'1234567890'].map(key => `Digit${key}`).concat([...'QWERTYUIOPASDFGHJKLZXCVBNM'].map(key => `Key${key}`));
export const soundCodes = [...playableCodes, 'Space', 'Minus', 'Equal', 'BracketLeft', 'BracketRight', 'Semicolon', 'Quote', 'Comma', 'Period', 'Slash', 'Enter', 'Backspace', 'ShiftLeft', 'ShiftRight', 'ControlLeft', 'AltLeft', 'ArrowUp', 'ArrowLeft', 'ArrowDown', 'ArrowRight', 'Backquote', 'Tab', 'Backslash', 'CapsLock', 'AltRight', 'ControlRight', 'MetaLeft', 'Fn', 'Escape', 'Delete', 'Home', 'PageUp', 'PageDown', 'End', ...Array.from({ length: 12 }, (_, i) => `F${i + 1}`)];
export const keyLabel = code => code.replace(/^(Key|Digit)/, '');

export function randomKeys(random = Math.random) {
  const pool = [...playableCodes];
  const count = 1 + Math.floor(random() * 5);
  const result = [];
  while (result.length < count) result.push(pool.splice(Math.floor(random() * pool.length), 1)[0]);
  return result;
}


// Keep the actual held keys: tapping a sequence must never complete a chord.
export function beginReaction(targets, now, down = []) {
  return { targets, down: [...down], phase: down.length ? 'waiting' : 'ready', startedAt: down.length ? null : now, reactionMs: null };
}

export function pressReaction(state, code, now) {
  if (state.down.includes(code)) return { state, wrong: false };
  const down = [...state.down, code];
  const wrong = state.phase === 'ready' && !state.targets.includes(code);
  const complete = state.phase === 'ready' && down.length === state.targets.length && state.targets.every(key => down.includes(key));
  return { state: { ...state, down, ...(complete ? { phase: 'success', reactionMs: Math.max(0, Math.round(now - state.startedAt)) } : {}) }, wrong };
}

export function releaseReaction(state, code, now) {
  const down = state.down.filter(key => key !== code);
  // A pre-held key cannot count toward the next round. Wait for a clean release.
  if (state.phase === 'waiting' && !down.length) return { ...state, down, phase: 'ready', startedAt: now };
  return { ...state, down };
}
