import { desktopObjects, layout, monitorScreens } from './layout.mjs';

export const easeCamera = t => t * t * (3 - 2 * t);
const distance = (a, b) => Math.hypot(...a.map((value, i) => value - b[i]));
const mix = (a, b, t) => a.map((value, i) => value + (b[i] - value) * t);
const assembly = desktopObjects.find(item => item.name === 'monitor');
const obstacles = monitorScreens.map(screen => ({
  center: [assembly.x + screen.position[0], layout.desk.top + screen.position[1], assembly.z],
  half: [screen.width / 2 + .19, screen.height / 2 + .19, .28],
}));
obstacles.push({ center: [-.5, 2.04, -.63], half: [1.16, .76, .22] });

function pointAt(points, t) {
  if (points.length === 2) return mix(points[0], points[1], t);
  const a = mix(points[0], points[1], t), b = mix(points[1], points[2], t), c = mix(points[2], points[3], t);
  return mix(mix(a, b, t), mix(b, c, t), t);
}
function clearsDesk(points) {
  for (let i = 0; i <= 240; i++) {
    const p = pointAt(points, i / 240);
    if (obstacles.some(({ center, half }) => p.every((v, axis) => Math.abs(v - center[axis]) < half[axis]))) return false;
  }
  return true;
}

export function makeCameraPath(from, to, avoidDesk = false) {
  let points = [from, to];
  if (avoidDesk && !clearsDesk(points)) {
    // A single continuous arc over the screens, rather than three stop/start
    // moves above the walls. Only lift paths that actually cross the displays.
    for (let height = 3.35; height <= 8; height += .15) {
      const control = (end, other) => {
        const p = mix(end, other, .5);
        p[1] = Math.max(height, end[1]);
        if (end[2] < -.85) { p[0] = end[0]; p[2] = end[2] - .25; }
        return p;
      };
      points = [from, control(from, to), control(to, from), to];
      if (clearsDesk(points)) break;
    }
  }
  // Arc-length lookup keeps speed even through bends; ease only at the two ends.
  const lengths = [0]; let previous = from;
  for (let i = 1; i <= 160; i++) {
    const p = pointAt(points, i / 160);
    lengths.push(lengths[i - 1] + distance(previous, p)); previous = p;
  }
  return { points, lengths };
}

export function sampleCameraPath(path, progress) {
  if (progress <= 0) return [...path.points[0]];
  if (progress >= 1) return [...path.points[path.points.length - 1]];
  const total = path.lengths[path.lengths.length - 1];
  if (total < .00001) return [...path.points[0]];
  const desired = easeCamera(progress) * total;
  const index = path.lengths.findIndex(length => length >= desired);
  const local = (desired - path.lengths[index - 1]) / (path.lengths[index] - path.lengths[index - 1]);
  return pointAt(path.points, (index - 1 + local) / (path.lengths.length - 1));
}
