import React, { createContext, useContext, useEffect, useState } from 'react';
import { Html } from '@react-three/drei';

export const InteractionLabels = createContext({ showAll: false, enabled: true });

export default function InteractionLabel({ name, position = [0, 0.3, 0], available = true, children }) {
  const { showAll, enabled } = useContext(InteractionLabels);
  const [hovered, setHovered] = useState(false);
  useEffect(() => { if (!enabled || !available) setHovered(false); }, [enabled, available]);
  return <group onPointerOver={event => { if (available && enabled) { event.stopPropagation(); setHovered(true); } }}
    onPointerOut={() => setHovered(false)}>
    {children}
    {available && enabled && (showAll || hovered) && <Html position={position} center zIndexRange={[4, 1]} style={{ pointerEvents: 'none' }}>
      <span className='object-label' role='tooltip'>{name}</span>
    </Html>}
  </group>;
}
