import React, { useEffect } from 'react';
import { useLoader, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { Box, Cylinder } from './primitives';
import useInspection from './useInspection';

const homePosition = new THREE.Vector3();
const homeRotation = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1, 0, 0), -Math.PI / 2);
const framing = { width: 0.48, height: 0.63 };

export default function ResumeClipboard({ wood, inspecting, onInspect, reducedMotion }) {
  const page = useLoader(THREE.TextureLoader, `${process.env.PUBLIC_URL}/assets/images/resume-handwritten.png`);
  const { ref, handlers } = useInspection({ inspecting, onInspect, reducedMotion, homePosition, homeRotation, framing, wheelMode: 'zoom' });
  const { gl } = useThree();
  useEffect(() => {
    page.colorSpace = THREE.SRGBColorSpace;
    page.anisotropy = Math.min(16, gl.capabilities.getMaxAnisotropy());
    page.needsUpdate = true;
  }, [page, gl]);

  return <group ref={ref} position={homePosition} quaternion={homeRotation} name='Pick up Marco’s handwritten résumé' {...handlers}>
    <group rotation={[Math.PI / 2, 0, 0]}>
    <Box args={[0.48, 0.025, 0.63]} position={[0, 0.0125, 0]} color='#845736' map={wood} radius={0.013} />
    <mesh position={[0, 0.027, 0.012]} castShadow={!inspecting}>
      <boxGeometry args={[0.438, 0.004, 0.566824]} />
      {[0, 1, 2, 3, 4, 5].map(face => <meshBasicMaterial key={face} attach={`material-${face}`}
        map={face === 2 ? page : null} color={face === 2 ? '#ffffff' : '#eeeae2'} toneMapped={false} />)}
    </mesh>
    <Box args={[0.155, 0.016, 0.032]} position={[0, 0.033, -0.292]} color='#858887' radius={0.005} />
    <Box args={[0.132, 0.006, 0.019]} position={[0, 0.043, -0.27]} color='#b9b8af' radius={0.002} />
    {[-0.054, 0.054].map(x => <Cylinder key={x} args={[0.007, 0.007, 0.003, 16]} position={[x, 0.042, -0.294]} color='#d5d2c9' />)}
    <mesh position={[0, 0.04, -0.30]} rotation={[-Math.PI / 2, 0, 0]}>
      <torusGeometry args={[0.015, 0.003, 8, 24]} /><meshStandardMaterial color='#a8aba5' metalness={0.55} roughness={0.35} />
    </mesh>
    </group>
  </group>;
}
