import React, { useEffect, useLayoutEffect, useRef } from 'react';
import { useFrame, useLoader, useThree } from '@react-three/fiber';
import * as THREE from 'three';
import { projects } from '../../constants/projectData';
import InteractionLabel from './InteractionLabel';
import { createProjectCarousel } from './carousel/createProjectCarousel';

const artworkNames = ['carousel-panels.png', 'carousel-column.png', 'carousel-base.png'];
const urls = [...artworkNames.map(name => `${process.env.PUBLIC_URL}/assets/carousel/${name}`), ...projects.map(project => project.image)];

export default function ProjectCarousel({ autoRotate, night, reducedMotion, focused, activeIndex, blocked, onFocus, onSelect }) {
  const host = useRef();
  const model = useRef();
  const maps = useLoader(THREE.TextureLoader, urls);
  const { gl } = useThree();
  useLayoutEffect(() => {
    const parent = host.current;
    const carousel = createProjectCarousel({
      projects,
      images: maps.slice(3).map(map => map.image),
      artwork: Object.fromEntries(artworkNames.map((name, i) => [name, maps[i]])),
      anisotropy: Math.min(8, gl.capabilities.getMaxAnisotropy()),
      pixelRatio: gl.getPixelRatio(),
    });
    model.current = carousel;
    parent.add(carousel.root);
    return () => { parent.remove(carousel.root); carousel.dispose(); model.current = null; };
  }, [maps, gl]);
  useEffect(() => { model.current?.turnTo(activeIndex); }, [activeIndex, focused]);
  useFrame((_, delta) => model.current?.update(delta, night, reducedMotion, focused, blocked, autoRotate));
  return <InteractionLabel name="Project carousel · click to explore" position={[0, .83, 0]}>
    <group ref={host} scale={.115} dispose={null}
      onClick={event => {
        event.stopPropagation();
        if (event.delta > 5 || blocked) return;
        const index = event.object.userData.photo;
        if (Number.isInteger(index)) onSelect(index);
        else onFocus();
      }} />
  </InteractionLabel>;
}
