import React, { useEffect, useMemo, useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { RoundedBox } from '@react-three/drei';
import * as THREE from 'three';
import { Box } from './primitives';
import { keyboardKeys as keys, keyboardColors, keyUnit } from './keyboardLayout.mjs';

function Keycap({ item, index, atlas, lit, pressed, error, onPress }) {
  const ref = useRef();
  const geometry = useMemo(() => {
    const plane = new THREE.PlaneGeometry(item.width * keyUnit - 0.012, 0.028);
    const uv = plane.attributes.uv;
    for (let i = 0; i < uv.count; i++) uv.setXY(i, ((index % 16) + uv.getX(i)) / 16, 1 - (Math.floor(index / 16) + 1 - uv.getY(i)) / 8);
    return plane;
  }, [item.width, index]);
  useEffect(() => () => geometry.dispose(), [geometry]);
  useFrame((_, delta) => { if (ref.current) ref.current.position.y = THREE.MathUtils.damp(ref.current.position.y, pressed ? 0.044 : 0.052, 24, delta); });
  return <group ref={ref} position={[item.x, 0.052, item.z]} name={`Keyboard ${item.label}`}
    onPointerDown={event => { event.stopPropagation(); if (event.button === 0) onPress(item.code); }} onClick={event => event.stopPropagation()}>
    <RoundedBox args={[item.width * keyUnit - 0.0035, 0.026, keyUnit - 0.0035]} radius={0.004} smoothness={3} castShadow receiveShadow>
      <meshStandardMaterial color={error ? '#f05b61' : lit ? '#a3ddb9' : keyboardColors[item.color]} roughness={0.4} />
    </RoundedBox>
    <RoundedBox args={[item.width * keyUnit - 0.011, 0.006, keyUnit - 0.012]} position={[0, 0.012, -0.001]} radius={0.0025} smoothness={3} receiveShadow>
      <meshStandardMaterial color={error ? '#ff6b70' : lit ? '#baf3ce' : pressed ? '#d9c8f1' : keyboardColors[item.color]} roughness={0.36}
        emissive={error ? '#ff2638' : lit ? '#68eba2' : '#ab91db'} emissiveIntensity={error ? 0.85 : lit ? 0.5 : pressed ? 0.35 : 0} />
    </RoundedBox>
    <mesh geometry={geometry} position={[0, 0.0152, -0.005]} rotation={[-Math.PI / 2, 0, 0]}>
      <meshBasicMaterial map={atlas} transparent depthWrite={false} color={lit ? '#274b3a' : item.color === 'white' ? '#777993' : '#f4f1ff'} />
    </mesh>
  </group>;
}

export default function GamingKeyboard({ active, onActivate, game }) {
  const ring = useRef(); const knob = useRef(); const dragging = useRef();
  const atlas = useMemo(() => {
    const canvas = document.createElement('canvas'); canvas.width = 2048; canvas.height = 1024;
    const ctx = canvas.getContext('2d'); ctx.fillStyle = '#fff'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    keys.forEach((key, index) => {
      ctx.font = `500 ${key.label.length > 2 ? 25 : key.label.length === 2 ? 40 : 49}px sans-serif`;
      ctx.fillText(key.label, (index % 16) * 128 + 64, Math.floor(index / 16) * 128 + 43, 110);
    });
    const map = new THREE.CanvasTexture(canvas); map.colorSpace = THREE.SRGBColorSpace; map.anisotropy = 4; return map;
  }, []);
  useEffect(() => () => atlas.dispose(), [atlas]);
  useFrame(({ clock }) => {
    if (ring.current) ring.current.emissiveIntensity = active ? 0.8 + 0.6 * Math.sin(clock.elapsedTime * 4) : 0.18;
    if (knob.current) knob.current.rotation.y = (0.5 - game.volume) * Math.PI * 1.5;
  });
  const press = code => active ? game.play(code) : onActivate();
  return <group name='Silver and lavender 75% mechanical keyboard' onClick={event => { event.stopPropagation(); if (!active && event.delta <= 5) onActivate(); }}>
    <RoundedBox args={[0.95, 0.034, 0.395]} position={[0, 0.017, 0]} radius={0.006} smoothness={3} castShadow receiveShadow>
      <meshStandardMaterial color='#bfc3cb' metalness={0.42} roughness={0.33} />
    </RoundedBox>
    <Box args={[0.909, 0.004, 0.354]} position={[0, 0.035, 0]} color='#626371' radius={0.004} />
    <Box args={[0.905, 0.004, 0.011]} position={[0, 0.038, -0.122]} color='#bec1c9' radius={0.001} />
    <Box args={[0.012, 0.004, 0.224]} position={[0.379, 0.038, 0.004]} color='#b9bdc7' radius={0.001} />
    {[-0.048, -0.016, 0.016].map((z, i) => <mesh key={z} position={[0.379, 0.041, z]} rotation={[-Math.PI / 2, 0, 0]}>
      <circleGeometry args={[0.0018, 12]} /><meshStandardMaterial color={i === 0 && active ? '#9fb8e7' : '#53566c'} emissive='#96a2da' emissiveIntensity={i === 0 && active ? 0.7 : 0} />
    </mesh>)}
    {keys.map((key, index) => <Keycap key={key.code} item={key} index={index} atlas={atlas}
      error={game.error} lit={game.targets.includes(key.code)} pressed={game.pressed.includes(key.code)} onPress={press} />)}
    <group position={[0.417, 0.035, -0.157]} name='Volume dial — click to start, drag to adjust'
      onPointerDown={event => {
        event.stopPropagation(); if (!active) { onActivate(); return; }
        dragging.current = { id: event.pointerId, x: event.clientX, y: event.clientY, volume: game.volume, moved: false };
        event.target.setPointerCapture(event.pointerId);
      }}
      onPointerMove={event => {
        const drag = dragging.current; if (!drag || drag.id !== event.pointerId) return;
        event.stopPropagation(); const delta = event.clientX - drag.x + drag.y - event.clientY;
        if (Math.hypot(event.clientX - drag.x, event.clientY - drag.y) > 4) drag.moved = true;
        game.setVolume(THREE.MathUtils.clamp(drag.volume + delta / 180, 0, 1));
      }}
      onPointerUp={event => {
        const drag = dragging.current; if (!drag) return;
        event.stopPropagation(); event.target.releasePointerCapture(event.pointerId); dragging.current = null;
        if (!drag.moved) game.start();
      }} onPointerCancel={() => { dragging.current = null; }} onClick={event => event.stopPropagation()}>
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.005, 0]}><torusGeometry args={[0.033, 0.0035, 8, 40]} />
        <meshStandardMaterial ref={ring} color='#cec5f3' emissive='#b5a3eb' emissiveIntensity={0.8} /></mesh>
      <group ref={knob}>
        <mesh position={[0, 0.019, 0]} castShadow><cylinderGeometry args={[0.029, 0.0305, 0.026, 64]} /><meshStandardMaterial color='#e0e3e7' metalness={0.65} roughness={0.3} /></mesh>
        <mesh position={[0, 0.0323, 0]}><cylinderGeometry args={[0.0275, 0.0275, 0.001, 64]} /><meshStandardMaterial color='#ebedf1' metalness={0.36} roughness={0.44} /></mesh>
        <Box args={[0.0015, 0.001, 0.007]} position={[0, 0.0333, -0.021]} color='#959aaa' radius={0.0004} />
        {Array.from({ length: 48 }, (_, i) => <Box key={i} args={[0.0008, 0.019, 0.0008]} position={[Math.sin(i * Math.PI / 24) * 0.03, 0.019, Math.cos(i * Math.PI / 24) * 0.03]} color='#a9adb8' radius={0.0003} />)}
      </group>
    </group>
  </group>;
}
